import XEUtils from 'xe-utils';
export function getChunkDefaultNum(selectKey) {
    const currDate = new Date();
    switch (selectKey) {
        case 'y': return currDate.getFullYear();
        case 'M': return currDate.getMonth() + 1;
        case 'd': return currDate.getDate();
        case 'H': return currDate.getHours();
        case 'm': return currDate.getMinutes();
        case 's': return currDate.getSeconds();
    }
    return 0;
}
export function hasTimestampValueType(valueFormat) {
    return valueFormat === 'timestamp';
}
export function hasDateValueType(valueFormat) {
    return valueFormat === 'date';
}
export function handleValueFormat(type, valueFormat) {
    if (valueFormat) {
        if (!(hasDateValueType(valueFormat) || hasTimestampValueType(valueFormat))) {
            return valueFormat;
        }
    }
    if (type === 'time') {
        return 'HH:mm:ss';
    }
    if (type === 'datetime') {
        return 'yyyy-MM-dd HH:mm:ss';
    }
    return 'yyyy-MM-dd';
}
export function toStringTimeDate(str) {
    const rest = new Date(2e3, 0, 1);
    if (str) {
        let h = 0;
        let m = 0;
        let s = 0;
        if (XEUtils.isNumber(str) || /^[0-9]{11,15}$/.test(`${str}`)) {
            str = new Date(Number(str));
        }
        if (XEUtils.isDate(str)) {
            h = str.getHours();
            m = str.getMinutes();
            s = str.getSeconds();
        }
        else {
            str = XEUtils.toValueString(str);
            const parses = str.match(/^(\d{1,2})(:(\d{1,2}))?(:(\d{1,2}))?/);
            if (parses) {
                h = XEUtils.toNumber(parses[1]);
                m = XEUtils.toNumber(parses[3]);
                s = XEUtils.toNumber(parses[5]);
            }
        }
        rest.setHours(h);
        rest.setMinutes(m);
        rest.setSeconds(s);
        return rest;
    }
    return rest;
}
export function getDateQuarter(date) {
    const month = date.getMonth();
    if (month < 3) {
        return 1;
    }
    else if (month < 6) {
        return 2;
    }
    else if (month < 9) {
        return 3;
    }
    return 4;
}
export function parseDateValue(val, type, options) {
    const { valueFormat } = options;
    if (val) {
        if (type === 'time') {
            return toStringTimeDate(XEUtils.isArray(val) ? XEUtils.last(val) : val);
        }
        if (XEUtils.isNumber(val) || /^[0-9]{10,15}$/.test(`${val}`)) {
            return new Date(Number(val));
        }
        if (XEUtils.isString(val)) {
            return XEUtils.toStringDate(XEUtils.last(val.split(',')), valueFormat);
        }
        if (XEUtils.isArray(val)) {
            return XEUtils.toStringDate(XEUtils.last(val), valueFormat);
        }
        return XEUtils.toStringDate(val, valueFormat);
    }
    return null;
}
export const parseDateString = (val, type, options) => {
    const dValue = parseDateValue(val, type, options);
    return dValue ? XEUtils.toDateString(dValue, options.valueFormat) : '';
};
export function parseDateObj(val, type, options) {
    const { labelFormat, firstDay } = options;
    let dValue = null;
    let dLabel = '';
    if (val) {
        dValue = parseDateValue(val, type, options);
    }
    if (XEUtils.isValidDate(dValue)) {
        dLabel = XEUtils.toDateString(dValue, labelFormat, { firstDay });
        // 周选择器，由于年份和第几周是冲突的行为，所以需要特殊处理，判断是否跨年，例如
        // '2024-12-31' 'yyyy-MM-dd W' >> '2024-12-31 1'
        // '2025-01-01' 'yyyy-MM-dd W' >> '2025-01-01 1'
        if (labelFormat && type === 'week') {
            const oldYyyy = dValue.getFullYear();
            const M = dValue.getMonth() + 1;
            const W = XEUtils.getYearWeek(dValue, firstDay);
            if (checkWeekOfsetYear(W, M)) {
                const formatY = 'yyyy';
                const newYyyy = oldYyyy + 1;
                const yyIndex = labelFormat.indexOf(formatY);
                if (yyIndex > -1) {
                    dLabel = dLabel.substring(0, yyIndex) + newYyyy + dLabel.substring(yyIndex + formatY.length);
                }
            }
        }
    }
    else {
        dValue = null;
    }
    return { label: dLabel, value: dValue };
}
export function getDateByCode(code, val, type, options) {
    const { valueFormat, firstDay } = options;
    let dValue = null;
    const value = (code === 'prev' || code === 'next' ? new Date() : (val ? parseDateValue(val, type, options) : null)) || new Date();
    switch (code) {
        case 'prev':
        case 'next':
        case 'minus':
        case 'plus': {
            const offsetNum = code === 'plus' || code === 'next' ? 1 : -1;
            switch (type) {
                case 'date':
                case 'datetime':
                    dValue = XEUtils.getWhatDay(value, offsetNum);
                    break;
                case 'week':
                    dValue = XEUtils.getWhatWeek(value, offsetNum, firstDay, firstDay);
                    break;
                case 'month':
                    dValue = XEUtils.getWhatMonth(value, offsetNum);
                    break;
                case 'quarter':
                    dValue = XEUtils.getWhatQuarter(value, offsetNum);
                    break;
                case 'year':
                    dValue = XEUtils.getWhatYear(value, offsetNum);
                    break;
            }
            break;
        }
        default:
            dValue = new Date();
            break;
    }
    return {
        value: dValue ? XEUtils.toDateString(dValue, valueFormat) : ''
    };
}
const rangeDateOffsetNumMaps = {
    last180: -180,
    last90: -90,
    last60: -60,
    last30: -30,
    last7: -7,
    last3: -3,
    last1: -1
};
function getRangeDateOffsetNum(code) {
    return rangeDateOffsetNumMaps[code] || 0;
}
export function getRangeDateByCode(code, val, type, options) {
    const { valueFormat, firstDay } = options;
    if (XEUtils.isArray(val)) {
        val = val.join('');
    }
    const value = (val ? parseDateValue(val, type, options) : null) || new Date();
    let sValue = null;
    const eValue = value;
    switch (code) {
        case 'last1':
        case 'last3':
        case 'last7':
        case 'last30':
        case 'last60':
        case 'last90':
        case 'last180': {
            const offsetNum = getRangeDateOffsetNum(code);
            switch (type) {
                case 'date':
                case 'datetime':
                    sValue = XEUtils.getWhatDay(value, offsetNum);
                    break;
                case 'week':
                    sValue = XEUtils.getWhatWeek(value, offsetNum, firstDay, firstDay);
                    break;
                case 'month':
                    sValue = XEUtils.getWhatMonth(value, offsetNum);
                    break;
                case 'quarter':
                    sValue = XEUtils.getWhatQuarter(value, offsetNum);
                    break;
                case 'year':
                    sValue = XEUtils.getWhatYear(value, offsetNum);
                    break;
            }
            break;
        }
        default:
            sValue = new Date();
            break;
    }
    const startValue = sValue ? XEUtils.toDateString(sValue, valueFormat) : '';
    const endValue = eValue ? XEUtils.toDateString(eValue, valueFormat) : '';
    return {
        startValue,
        endValue
    };
}
/**
 * 判断周的年份是否跨年
 */
function checkWeekOfsetYear(W, M) {
    return `${W}` === '1' && `${M}` === '12';
}
export function isAllSameChar(str, char) {
    if (str.length === 0) {
        return false;
    }
    for (let i = 0; i < str.length; i++) {
        if (str[i] !== char) {
            return false;
        }
    }
    return true;
}
export function checkDateInputFormat(numStr, formatKey) {
    const numVal = XEUtils.toNumber(numStr);
    switch (formatKey) {
        case 'yyyy':
            return (numVal >= 9999 ? 9999 : (numVal <= 0 ? 0 : numVal));
        case 'MM':
            return (numVal >= 12 ? 12 : (numVal <= 0 ? 0 : numVal));
        case 'dd':
            return (numVal >= 31 ? 31 : (numVal <= 0 ? 0 : numVal));
        case 'HH':
        case 'mm':
        case 'ss':
            return (numVal >= 59 ? 59 : (numVal <= 0 ? 0 : numVal));
    }
    return numVal;
}
export const getPrevYear = (date, size = 1) => {
    const currtYear = date.getFullYear();
    date.setFullYear(currtYear - size);
    return date;
};
export const getNextYear = (date, size = 1) => {
    const currtYear = date.getFullYear();
    date.setFullYear(currtYear + size);
    return date;
};
export const getPrevMonth = (date) => {
    const currtYear = date.getFullYear();
    const currMonth = date.getMonth();
    if (currMonth) {
        date.setMonth(currMonth - 1);
    }
    else {
        date.setFullYear(currtYear - 1);
        date.setMonth(11);
    }
    return date;
};
export const getNextMonth = (date) => {
    const currtYear = date.getFullYear();
    const currMonth = date.getMonth();
    if (currMonth < 11) {
        date.setMonth(currMonth + 1);
    }
    else {
        date.setFullYear(currtYear + 1);
        date.setMonth(0);
    }
    return date;
};
