import { h, ref, computed, nextTick, watch, reactive, inject, onMounted } from 'vue';
import { defineVxeComponent } from '../../ui/src/comp';
import XEUtils from 'xe-utils';
import { getConfig, getIcon, getI18n, createEvent, useSize, renderEmptyElement } from '../../ui';
import { getFuncText } from '../../ui/src/utils';
import { createComponentLog } from '../../ui/src/log';
const { warnLog } = createComponentLog('textarea');
let autoTxtElem;
export default defineVxeComponent({
    name: 'VxeTextarea',
    props: {
        modelValue: [String, Number],
        className: String,
        inputClassName: {
            type: String,
            default: () => getConfig().textarea.inputClassName
        },
        immediate: {
            type: Boolean,
            default: true
        },
        name: String,
        readonly: {
            type: Boolean,
            default: null
        },
        editable: {
            type: Boolean,
            default: true
        },
        disabled: {
            type: Boolean,
            default: null
        },
        clearable: {
            type: Boolean,
            default: () => getConfig().textarea.clearable
        },
        placeholder: String,
        maxLength: [String, Number],
        trim: {
            type: Boolean,
            default: () => getConfig().textarea.trim
        },
        rows: {
            type: [String, Number],
            default: null
        },
        cols: {
            type: [String, Number],
            default: null
        },
        showWordCount: Boolean,
        countMethod: Function,
        autoFocus: {
            type: Boolean,
            default: null
        },
        /**
         * 已废弃，被 auto-size 替换
         * @deprecated
         */
        autosize: {
            type: [Boolean, Object],
            default: null
        },
        autoSize: {
            type: [Boolean, Object],
            default: null
        },
        form: String,
        resize: {
            type: String,
            default: () => getConfig().textarea.resize
        },
        size: {
            type: String,
            default: () => getConfig().textarea.size || getConfig().size
        },
        // 已废弃
        maxlength: [String, Number]
    },
    emits: [
        'update:modelValue',
        'input',
        'keydown',
        'keyup',
        'click',
        'change',
        'focus',
        'blur',
        'clear',
        'lazy-change'
    ],
    setup(props, context) {
        const { emit } = context;
        const $xeForm = inject('$xeForm', null);
        const formItemInfo = inject('xeFormItemInfo', null);
        const xID = XEUtils.uniqueId();
        const { computeSize } = useSize(props);
        const reactData = reactive({
            inputValue: props.modelValue
        });
        const refElem = ref();
        const refTextarea = ref();
        const refContent = ref();
        const refMaps = {
            refElem,
            refTextarea
        };
        const $xeTextarea = {
            xID,
            props,
            context,
            reactData,
            getRefMaps: () => refMaps
        };
        const computeFormReadonly = computed(() => {
            const { readonly } = props;
            if (readonly === null) {
                if ($xeForm) {
                    return $xeForm.props.readonly;
                }
                return false;
            }
            return readonly;
        });
        const computeIsDisabled = computed(() => {
            const { disabled } = props;
            if (disabled === null) {
                if ($xeForm) {
                    return $xeForm.props.disabled;
                }
                return false;
            }
            return disabled;
        });
        const computeInputReadonly = computed(() => {
            const { editable, readonly } = props;
            return readonly || !editable;
        });
        const computeInpPlaceholder = computed(() => {
            const { placeholder } = props;
            if (placeholder) {
                return getFuncText(placeholder);
            }
            const globalPlaceholder = getConfig().textarea.placeholder;
            if (globalPlaceholder) {
                return getFuncText(globalPlaceholder);
            }
            return getI18n('vxe.base.pleaseInput');
        });
        const computeInpMaxLength = computed(() => {
            const { maxLength, maxlength } = props;
            return maxLength || maxlength;
        });
        const computeInputCount = computed(() => {
            return XEUtils.getSize(reactData.inputValue);
        });
        const computeIsCountError = computed(() => {
            const inputCount = computeInputCount.value;
            const inpMaxLength = computeInpMaxLength.value;
            return inpMaxLength && inputCount > XEUtils.toNumber(inpMaxLength);
        });
        const computeSizeOpts = computed(() => {
            const { autosize, autoSize } = props;
            if (autosize || getConfig().textarea.autosize) {
                return Object.assign({ minRows: 1, maxRows: 10 }, getConfig().textarea.autosize, autosize);
            }
            return Object.assign({ minRows: 1, maxRows: 10 }, getConfig().textarea.autoSize, autoSize);
        });
        const computeDomValue = computed(() => {
            const { inputValue } = reactData;
            return inputValue;
        });
        const dispatchEvent = (type, params, evnt) => {
            emit(type, createEvent(evnt, { $textarea: $xeTextarea }, params));
        };
        const updateDomValue = () => {
            const domValue = computeDomValue.value;
            const taElem = refTextarea.value;
            if (taElem) {
                taElem.value = XEUtils.eqNull(domValue) ? '' : ('' + domValue);
            }
        };
        const updateAutoTxt = () => {
            const { size, autosize, autoSize } = props;
            const { inputValue } = reactData;
            if (autosize || autoSize) {
                const formReadonly = computeFormReadonly.value;
                if (!autoTxtElem) {
                    autoTxtElem = document.createElement('div');
                }
                if (!autoTxtElem.parentNode) {
                    document.body.appendChild(autoTxtElem);
                }
                const taElem = refTextarea.value;
                const ctElem = refContent.value;
                const textElem = formReadonly ? ctElem : taElem;
                if (!textElem) {
                    return;
                }
                const textStyle = getComputedStyle(textElem);
                autoTxtElem.className = ['vxe-textarea--autosize', size ? `size--${size}` : ''].join(' ');
                autoTxtElem.style.width = `${textElem.clientWidth}px`;
                autoTxtElem.style.padding = textStyle.padding;
                autoTxtElem.innerText = ('' + (inputValue || '　')).replace(/\n$/, '\n　');
            }
        };
        const handleResize = () => {
            const { autosize, autoSize } = props;
            if (autosize || autoSize) {
                nextTick(() => {
                    const sizeOpts = computeSizeOpts.value;
                    const formReadonly = computeFormReadonly.value;
                    const { minRows, maxRows } = sizeOpts;
                    const taElem = refTextarea.value;
                    const ctElem = refContent.value;
                    const textElem = formReadonly ? ctElem : taElem;
                    if (!textElem) {
                        return;
                    }
                    const sizeHeight = autoTxtElem.clientHeight;
                    const textStyle = getComputedStyle(textElem);
                    const lineHeight = XEUtils.toNumber(textStyle.lineHeight);
                    const paddingTop = XEUtils.toNumber(textStyle.paddingTop);
                    const paddingBottom = XEUtils.toNumber(textStyle.paddingBottom);
                    const borderTopWidth = XEUtils.toNumber(textStyle.borderTopWidth);
                    const borderBottomWidth = XEUtils.toNumber(textStyle.borderBottomWidth);
                    const intervalHeight = paddingTop + paddingBottom + borderTopWidth + borderBottomWidth;
                    const rowNum = (sizeHeight - intervalHeight) / lineHeight;
                    const textRows = rowNum && /[0-9]/.test('' + rowNum) ? rowNum : Math.floor(rowNum) + 1;
                    let vaildRows = textRows;
                    if (textRows < minRows) {
                        vaildRows = minRows;
                    }
                    else if (textRows > maxRows) {
                        vaildRows = maxRows;
                    }
                    textElem.style.height = `${(vaildRows * lineHeight) + intervalHeight}px`;
                });
            }
        };
        const triggerEvent = (evnt) => {
            const value = reactData.inputValue;
            dispatchEvent(evnt.type, { value }, evnt);
        };
        const handleChange = (value, evnt) => {
            if (props.trim) {
                value = `${value || ''}`.trim();
            }
            reactData.inputValue = value;
            emit('update:modelValue', value);
            if (XEUtils.toValueString(props.modelValue) !== value) {
                dispatchEvent('change', { value }, evnt);
                // 自动更新校验状态
                if ($xeForm && formItemInfo) {
                    $xeForm.triggerItemEvent(evnt, formItemInfo.itemConfig.field, value);
                }
            }
        };
        const clearValueEvent = (evnt, value) => {
            const { autoFocus } = props;
            if (autoFocus || autoFocus === null) {
                focus();
            }
            handleChange('', evnt);
            dispatchEvent('clear', { value }, evnt);
        };
        const inputEvent = (evnt) => {
            const { immediate } = props;
            const textElem = evnt.target;
            const value = textElem.value;
            reactData.inputValue = value;
            if (immediate) {
                handleChange(value, evnt);
            }
            else {
                // 自动更新校验状态
                if ($xeForm && formItemInfo) {
                    $xeForm.triggerItemEvent(evnt, formItemInfo.itemConfig.field, value);
                }
            }
            dispatchEvent('input', { value }, evnt);
            handleResize();
        };
        const changeEvent = (evnt) => {
            const { immediate } = props;
            if (immediate) {
                triggerEvent(evnt);
            }
            else {
                handleChange(reactData.inputValue, evnt);
            }
            dispatchEvent('lazy-change', { value: reactData.inputValue }, evnt);
        };
        const blurEvent = (evnt) => {
            const { immediate } = props;
            const { inputValue } = reactData;
            if (!immediate) {
                handleChange(inputValue, evnt);
            }
            else {
                updateDomValue();
            }
            dispatchEvent('blur', { value: inputValue }, evnt);
        };
        const textareaMethods = {
            dispatchEvent,
            focus() {
                const textElem = refTextarea.value;
                textElem.focus();
                return nextTick();
            },
            blur() {
                const textElem = refTextarea.value;
                textElem.blur();
                return nextTick();
            }
        };
        Object.assign($xeTextarea, textareaMethods);
        const renderVN = () => {
            const { className, inputClassName, resize, autosize, autoSize, showWordCount, countMethod, rows, cols, clearable } = props;
            const { inputValue } = reactData;
            const vSize = computeSize.value;
            const isDisabled = computeIsDisabled.value;
            const isCountError = computeIsCountError.value;
            const inputCount = computeInputCount.value;
            const inputReadonly = computeInputReadonly.value;
            const formReadonly = computeFormReadonly.value;
            const inpPlaceholder = computeInpPlaceholder.value;
            const inpMaxLength = computeInpMaxLength.value;
            if (formReadonly) {
                return h('div', {
                    ref: refElem,
                    class: ['vxe-textarea--readonly', className]
                }, [
                    h('div', {
                        ref: refContent,
                        class: 'vxe-textarea--content'
                    }, inputValue)
                ]);
            }
            return h('div', {
                ref: refElem,
                class: ['vxe-textarea', className, {
                        [`size--${vSize}`]: vSize,
                        'is--autosize': autosize || autoSize,
                        'is--count': showWordCount,
                        'is--disabled': isDisabled,
                        'is-clear': clearable,
                        'is--rows': !XEUtils.eqNull(rows),
                        'is--cols': !XEUtils.eqNull(cols),
                        'show--clear': clearable && !isDisabled && !(inputValue === '' || XEUtils.eqNull(inputValue))
                    }],
                spellcheck: false
            }, [
                h('textarea', {
                    ref: refTextarea,
                    class: 'vxe-textarea--inner' + (inputClassName ? (' ' + inputClassName) : ''),
                    name: props.name,
                    placeholder: inpPlaceholder,
                    maxlength: inpMaxLength,
                    readonly: inputReadonly,
                    disabled: isDisabled,
                    rows,
                    cols,
                    style: resize
                        ? {
                            resize
                        }
                        : null,
                    onInput: inputEvent,
                    onChange: changeEvent,
                    onKeydown: triggerEvent,
                    onKeyup: triggerEvent,
                    onClick: triggerEvent,
                    onFocus: triggerEvent,
                    onBlur: blurEvent
                }),
                clearable || showWordCount
                    ? h('div', {
                        class: 'vxe-textarea--suffix'
                    }, [
                        clearable
                            ? h('div', {
                                class: 'vxe-textarea--clear-icon',
                                onClick: clearValueEvent
                            }, [
                                h('i', {
                                    class: getIcon().TEXTAREA_CLEAR
                                })
                            ])
                            : renderEmptyElement($xeTextarea),
                        showWordCount
                            ? h('span', {
                                class: ['vxe-textarea--count', {
                                        'is--error': isCountError
                                    }]
                            }, countMethod ? `${countMethod({ value: inputValue })}` : `${inputCount}${inpMaxLength ? `/${inpMaxLength}` : ''}`)
                            : renderEmptyElement($xeTextarea)
                    ])
                    : renderEmptyElement($xeTextarea)
            ]);
        };
        watch(() => props.modelValue, (val) => {
            reactData.inputValue = val;
            updateAutoTxt();
        });
        const reFlag = ref(0);
        watch(computeFormReadonly, () => {
            reFlag.value++;
        });
        watch(computeSizeOpts, () => {
            reFlag.value++;
        });
        watch(() => props.autoSize, () => {
            reFlag.value++;
        });
        watch(() => props.autosize, () => {
            reFlag.value++;
        });
        watch(reFlag, () => {
            updateAutoTxt();
            handleResize();
        });
        const rDvFlag = ref(0);
        watch(computeFormReadonly, () => {
            rDvFlag.value++;
        });
        watch(computeDomValue, () => {
            rDvFlag.value++;
        });
        watch(rDvFlag, () => {
            updateDomValue();
        });
        onMounted(() => {
            updateDomValue();
            nextTick(() => {
                updateDomValue();
            });
        });
        nextTick(() => {
            const { autosize, autoSize } = props;
            if (autosize) {
                warnLog('vxe.error.delProp', ['autosize', 'auto-size']);
            }
            if (autosize || autoSize) {
                updateAutoTxt();
                handleResize();
            }
        });
        $xeTextarea.renderVN = renderVN;
        return $xeTextarea;
    },
    render() {
        return this.renderVN();
    }
});
